if (!function_exists('calculate_age_shortcode')) {

    function calculate_age_shortcode($atts) {

        $atts = shortcode_atts(
            array(
                'dob' => '',
            ),
            $atts
        );

        // DOB empty check
        if (empty($atts['dob'])) {
            return '';
        }

        try {
            $birthDate = new DateTime($atts['dob']);
            $today     = new DateTime();
            $age       = $birthDate->diff($today)->y;
            return $age;

        } catch (Exception $e) {
            // Invalid date format – prevent site crash
            return '';
        }
    }

    add_shortcode('age', 'calculate_age_shortcode');
}
